import {
  validateBpmnActionTypes
} from "./packager-tool-nmznynbj.js";
import"./packager-tool-jfv7t0c8.js";
import {
  extractStartEventId,
  uploadAndDebugSolution
} from "./packager-tool-me5q0naa.js";
import"./packager-tool-qgh5yaeh.js";
import {
  buildSolutionPackageFromDir,
  createZipFromDir,
  uploadOrOverwriteSolution
} from "./packager-tool-7309ymg1.js";
import {
  findSolutionFile,
  updateSolutionFile
} from "./packager-tool-a6yfnjgx.js";
import"./packager-tool-nkrmjr3a.js";
import {
  logger
} from "./packager-tool-79gws1zn.js";
import {
  getFileSystem
} from "./packager-tool-0v3s8r01.js";
import"./packager-tool-1yh8g550.js";

// src/services/maestro-debug-service.ts
import crypto from "node:crypto";
class MaestroDebugService {
  fs;
  constructor() {
    this.fs = getFileSystem();
  }
  async readBpmnFile(bpmnFilePath) {
    const absolutePath = this.fs.path.resolve(bpmnFilePath);
    if (!await this.fs.exists(absolutePath)) {
      throw new Error(`File not found: ${absolutePath}`);
    }
    if (!absolutePath.endsWith(".bpmn")) {
      throw new Error(`Expected a .bpmn file but got: ${this.fs.path.basename(absolutePath)}`);
    }
    const content = await this.fs.readFile(absolutePath);
    return typeof content === "string" ? content : content.toString("utf-8");
  }
  async validateProjectBpmnActionTypes(absoluteProjectPath) {
    const contentDir = this.fs.path.join(absoluteProjectPath, "content");
    if (!await this.fs.exists(contentDir)) {
      return;
    }
    const entries = await this.fs.readdir(contentDir);
    for (const entry of entries) {
      if (!entry.endsWith(".bpmn")) {
        continue;
      }
      const bpmnPath = this.fs.path.join(contentDir, entry);
      const content = await this.fs.readFile(bpmnPath, "utf-8");
      if (!content) {
        continue;
      }
      const xml = typeof content === "string" ? content : content.toString();
      validateBpmnActionTypes(xml);
    }
  }
  async buildSolutionPackage(projectDir, projectName) {
    const solutionId = crypto.randomUUID();
    const projectId = crypto.randomUUID();
    const stagingDir = this.fs.path.join(this.fs.env.tmpdir(), `.maestro-debug-solution-${Date.now()}`);
    await this.fs.mkdir(stagingDir);
    const solutionStorage = {
      SolutionId: solutionId,
      Projects: [
        {
          ProjectId: projectId,
          ProjectRelativePath: `${projectName}/project.uiproj`
        }
      ]
    };
    await this.fs.writeFile(this.fs.path.join(stagingDir, "SolutionStorage.json"), JSON.stringify(solutionStorage));
    const uipx = {
      SolutionId: solutionId,
      Projects: [
        {
          Type: "processOrchestration",
          ProjectRelativePath: `${projectName}/project.uiproj`,
          Id: projectId
        }
      ]
    };
    await this.fs.writeFile(this.fs.path.join(stagingDir, `${projectName}Solution.uipx`), JSON.stringify(uipx, null, 2));
    const destProjectDir = this.fs.path.join(stagingDir, projectName);
    await this.fs.mkdir(destProjectDir);
    const copyDirRecursive = async (src, dest) => {
      await this.fs.mkdir(dest);
      const entries = await this.fs.readdir(src);
      for (const entry of entries) {
        const srcPath = this.fs.path.join(src, entry);
        const destPath = this.fs.path.join(dest, entry);
        const stat2 = await this.fs.stat(srcPath);
        if (stat2?.isDirectory?.()) {
          await copyDirRecursive(srcPath, destPath);
        } else {
          const content = await this.fs.readFile(srcPath);
          if (content === null) {
            throw new Error(`Failed to read file: ${srcPath}`);
          }
          await this.fs.writeFile(destPath, content);
        }
      }
    };
    const flattenCopy = async (src, dest) => {
      const entries = await this.fs.readdir(src);
      for (const entry of entries) {
        const srcPath = this.fs.path.join(src, entry);
        const stat2 = await this.fs.stat(srcPath);
        if (stat2?.isDirectory?.()) {
          if (entry === "content") {
            const innerEntries = await this.fs.readdir(srcPath);
            for (const inner of innerEntries) {
              const innerSrc = this.fs.path.join(srcPath, inner);
              const innerStat = await this.fs.stat(innerSrc);
              if (innerStat?.isDirectory?.()) {
                await copyDirRecursive(innerSrc, this.fs.path.join(dest, inner));
              } else {
                const content = await this.fs.readFile(innerSrc);
                if (content === null) {
                  throw new Error(`Failed to read file: ${innerSrc}`);
                }
                await this.fs.writeFile(this.fs.path.join(dest, inner), content);
              }
            }
          } else {
            await copyDirRecursive(srcPath, this.fs.path.join(dest, entry));
          }
        } else {
          const content = await this.fs.readFile(srcPath);
          if (content === null) {
            throw new Error(`Failed to read file: ${srcPath}`);
          }
          await this.fs.writeFile(this.fs.path.join(dest, entry), content);
        }
      }
    };
    await flattenCopy(projectDir, destProjectDir);
    const uisPath = this.fs.path.join(this.fs.env.tmpdir(), `${projectName}Solution-${Date.now()}.uis`);
    logger.info(`Zipping staging directory into ${uisPath}`);
    const zipData = await createZipFromDir(this.fs, stagingDir);
    await this.fs.writeFile(uisPath, zipData);
    const stat = await this.fs.stat(uisPath);
    logger.info(`Created .uis file: ${uisPath} (size: ${stat?.size || 0} bytes)`);
    await this.fs.rm(stagingDir);
    return uisPath;
  }
  async executeProjectViaStudioWeb(projectPath, pimsConfig, callbacks, pollInterval, options) {
    const absoluteProjectPath = this.fs.path.resolve(projectPath);
    const projectUiprojPath = this.fs.path.join(absoluteProjectPath, "project.uiproj");
    if (!await this.fs.exists(projectUiprojPath)) {
      throw new Error(`Not a valid maestro project directory: missing project.uiproj in ${absoluteProjectPath}`);
    }
    const projectUiprojContent = await this.fs.readFile(projectUiprojPath, "utf-8");
    if (projectUiprojContent === null) {
      throw new Error(`Could not read project.uiproj in ${absoluteProjectPath}`);
    }
    const projectUiproj = JSON.parse(projectUiprojContent);
    const projectName = projectUiproj.Name;
    const entryPointsPath = this.fs.path.join(absoluteProjectPath, "entry-points.json");
    if (!await this.fs.exists(entryPointsPath)) {
      throw new Error(`Not a valid maestro project directory: missing entry-points.json in ${absoluteProjectPath}`);
    }
    const entryPointsContent = await this.fs.readFile(entryPointsPath, "utf-8");
    if (entryPointsContent === null) {
      throw new Error(`Could not read entry-points.json in ${absoluteProjectPath}`);
    }
    const entryPointsJson = JSON.parse(entryPointsContent);
    const rawEntryPoint = entryPointsJson.entryPoints?.[0]?.filePath ?? "";
    const entryPoint = rawEntryPoint.replace(/^\/content/, "");
    await this.validateProjectBpmnActionTypes(absoluteProjectPath);
    logger.info("Looking for .uipx solution file...");
    const solutionInfo = await findSolutionFile(this.fs, absoluteProjectPath);
    const existingSolutionId = solutionInfo?.solutionId;
    logger.info("Building solution package from project...");
    const solutionDir = this.fs.path.resolve(absoluteProjectPath, "..");
    const uisPath = await buildSolutionPackageFromDir(this.fs, solutionDir);
    const apiConfig = {
      baseUrl: pimsConfig.baseUrl,
      organizationId: pimsConfig.organizationId,
      tenantName: pimsConfig.tenantName,
      tenantId: pimsConfig.tenantId,
      authToken: pimsConfig.authToken,
      organizationUnitId: pimsConfig.organizationUnitId
    };
    return uploadAndDebugSolution({
      upload: () => uploadOrOverwriteSolution(apiConfig, pimsConfig.organizationName, uisPath, existingSolutionId, this.fs),
      onSolutionId: (id) => updateSolutionFile(this.fs, absoluteProjectPath, id),
      projectName,
      entryPoint,
      projectType: "processOrchestration",
      apiConfig,
      organizationName: pimsConfig.organizationName,
      callbacks,
      pollInterval,
      beginSessionPayload: JSON.stringify(options?.inputs ?? {})
    });
  }
  async execute(filePath, pimsConfig, callbacks, pollInterval, options) {
    const lowerPath = filePath.toLowerCase();
    if (!lowerPath.endsWith(".bpmn")) {
      throw new Error(`Unsupported file type. Only .bpmn files are supported for Maestro debug.`);
    }
    logger.info("Reading .bpmn file...");
    const bpmnXml = await this.readBpmnFile(filePath);
    validateBpmnActionTypes(bpmnXml);
    const startEventId = extractStartEventId(bpmnXml);
    const projectName = this.fs.path.basename(filePath, ".bpmn");
    const safeName = projectName.replace(/[^a-zA-Z0-9_-]/g, "_");
    const projectDir = this.fs.path.join(this.fs.env.tmpdir(), `.maestro-debug-${safeName}-${Date.now()}`);
    logger.info("Generating project files...");
    await this.fs.mkdir(projectDir);
    await this.fs.mkdir(this.fs.path.join(projectDir, "content"));
    const projectId = crypto.randomUUID();
    const entryPointId = crypto.randomUUID();
    const operateJson = {
      $schema: "https://cloud.uipath.com/draft/2024-12/operate",
      projectId,
      main: `/content/${safeName}.bpmn#${startEventId}`,
      contentType: "ProcessOrchestration",
      targetFramework: "Portable",
      runtimeOptions: {
        requiresUserInteraction: false,
        isAttended: false
      }
    };
    const entryPointsJson = {
      $schema: "https://cloud.uipath.com/draft/2024-12/entry-point",
      $id: "entry-points.json",
      entryPoints: [
        {
          filePath: `/content/${safeName}.bpmn#${startEventId}`,
          uniqueId: entryPointId,
          type: "ProcessOrchestration",
          input: {
            type: "object",
            properties: {}
          },
          output: {
            type: "object",
            properties: {}
          },
          displayName: "Manual trigger"
        }
      ]
    };
    const bindingsJson = { version: "2.0", resources: [] };
    const packageDescriptorJson = {
      $schema: "https://cloud.uipath.com/draft/2024-12/package-descriptor",
      files: {
        "operate.json": "content/operate.json",
        "entry-points.json": "content/entry-points.json",
        "bindings.json": "content/bindings_v2.json",
        [`${safeName}.bpmn`]: `content/${safeName}.bpmn`
      }
    };
    const projectUiproj = {
      Name: projectName,
      ProjectType: "ProcessOrchestration"
    };
    await this.fs.writeFile(this.fs.path.join(projectDir, "project.uiproj"), JSON.stringify(projectUiproj, null, 2));
    await this.fs.writeFile(this.fs.path.join(projectDir, "content", "operate.json"), JSON.stringify(operateJson, null, 2));
    await this.fs.writeFile(this.fs.path.join(projectDir, "content", "entry-points.json"), JSON.stringify(entryPointsJson, null, 2));
    await this.fs.writeFile(this.fs.path.join(projectDir, "content", "bindings_v2.json"), JSON.stringify(bindingsJson, null, 2));
    await this.fs.writeFile(this.fs.path.join(projectDir, "content", "package-descriptor.json"), JSON.stringify(packageDescriptorJson, null, 2));
    await this.fs.writeFile(this.fs.path.join(projectDir, "content", `${safeName}.bpmn`), bpmnXml);
    logger.info("Building solution package...");
    const uisPath = await this.buildSolutionPackage(projectDir, safeName);
    const apiConfig = {
      baseUrl: pimsConfig.baseUrl,
      organizationId: pimsConfig.organizationId,
      tenantName: pimsConfig.tenantName,
      tenantId: pimsConfig.tenantId,
      authToken: pimsConfig.authToken,
      organizationUnitId: pimsConfig.organizationUnitId
    };
    return uploadAndDebugSolution({
      upload: () => uploadOrOverwriteSolution(apiConfig, pimsConfig.organizationName, uisPath, undefined, this.fs),
      projectName: safeName,
      entryPoint: `/${safeName}.bpmn#${startEventId}`,
      projectType: "processOrchestration",
      apiConfig,
      organizationName: pimsConfig.organizationName,
      callbacks,
      pollInterval,
      beginSessionPayload: JSON.stringify(options?.inputs ?? {})
    });
  }
}
export {
  MaestroDebugService
};

